        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    colors = [v for v in counts if v != bg]
    if not colors:
        return out
    fg = max(colors, key=counts.get)
    h, w = len(grid), len(grid[0])

    # For each row/column, fill the interval bounded by its first and last
    # occurrence of the non-background color; preserve the original marks.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        if len(cols) >= 2:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        if len(rows) >= 2:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

